public class LocalGlossaryTerm {public string Source,Target;}
public class LocalGlossaryProfile {
 public int Format=1;public string Id,Name,Language="*",Context="";public bool UseEnglishReference=true;public List<LocalGlossaryTerm> Terms=new List<LocalGlossaryTerm>();
 public override string ToString(){return Name;}
}
public class LocalContentEntry {
 public string Source,Target,Role,SourceHash,ReferenceHash,Origin="imported",OriginVersion,ModelHash,PolicyHash,Updated;
}
public class LocalDictionaryPack {
 public string Kind="Celesphonia.Dictionary",Id,Name,Family,OriginVersion,Language;public int Format=1;public List<LocalContentEntry> Entries=new List<LocalContentEntry>();public LocalGlossaryProfile Glossary;
 public override string ToString(){return Name+" · "+Language+" · "+Entries.Count.ToString("N0")+" entries";}
}
public class LocalImportPreview {public LocalDictionaryPack Pack;public int Applicable,Inactive,Invalid,Conflicts,Unchanged;public string Summary;}
public class LocalComparison {
 public Dictionary<string,string> English=new Dictionary<string,string>(),Model=new Dictionary<string,string>(),Imported=new Dictionary<string,string>(),User=new Dictionary<string,string>(),Effective=new Dictionary<string,string>(),Origins=new Dictionary<string,string>();
 public readonly Dictionary<string,Dictionary<string,string>> PackLayers=new Dictionary<string,Dictionary<string,string>>();public Dictionary<string,LocalResult> ModelRows=new Dictionary<string,LocalResult>();public Dictionary<string,LocalEdit> Edits=new Dictionary<string,LocalEdit>();public Dictionary<string,LocalDictionaryPack> Packs=new Dictionary<string,LocalDictionaryPack>();
}
public static class LocalLibrary {
 public static string Home {get{return LocalTranslation.Child(LocalTranslation.Home,"Library");}}
 static readonly object profilesGate=new object();static string profilesStamp;static List<LocalGlossaryProfile> cachedProfiles=new List<LocalGlossaryProfile>();
 public static string Key(string role,string source){return LocalTranslation.TextHash(role+"\u001fEnglishCoverage\u001f"+source);}
 public static string Version(string root){return UniversalSupport.Identify(root)??"unidentified";}
 public static string FamilyForVersion(string version){if(version.StartsWith("three-in-one-3-3-5-"))return "three-in-one-3-3-5";if(version.StartsWith("maple-"))return "maple";if(version.StartsWith("gorpg-"))return "gorpg";return version;}
 public static string Family(LocalRun run){return !string.IsNullOrEmpty(run.Family)?run.Family:FamilyForVersion(!string.IsNullOrEmpty(run.OriginVersion)?run.OriginVersion:Version(run.Root));}
 public static void Bind(LocalRun run){if(string.IsNullOrEmpty(run.Family)){run.OriginVersion=Version(run.Root);run.Family=FamilyForVersion(run.OriginVersion);if(run.Family=="unidentified")run.Family+="-"+run.GameKey;LocalTranslation.Save(run);}}
 public static string Revision(LocalRun run){return EnglishSupport.LocalCoverageRevision(run.Root)+"|"+EnglishRelease.Hash(EnglishRelease.Runtime());}
 public static bool Valid(string source,string target){if(string.IsNullOrWhiteSpace(source)||source.Length>12000||string.IsNullOrWhiteSpace(target)||target.Length>24000||!EnglishSupport.Compatible(source,target))return false;return Regex.Matches(source,@"\d+(?:\.\d+)?").Cast<Match>().Select(x=>x.Value).SequenceEqual(Regex.Matches(Regex.Replace(target,@"\b\d{1,3}(?:,\d{3})+\b",m=>m.Value.Replace(",","")),@"\d+(?:\.\d+)?").Cast<Match>().Select(x=>x.Value));}
 public static List<LocalGlossaryProfile> Profiles(string language){
  var result=new List<LocalGlossaryProfile>{new LocalGlossaryProfile{Id="rpg",Name="Fantasy RPG",Context="Fantasy role-playing game. Use concise, conventional game terminology. Preserve names and ATK, DEF, MAT, MDF, AGI, HP, MP and SP abbreviations. Translate only the supplied text."},new LocalGlossaryProfile{Id="adult-rpg",Name="Adult fantasy RPG",Context="Adult fantasy RPG localization. Use established terminology for status effects, equipment, arousal, hypnosis, restraints and aphrodisiacs. Preserve the source meaning and tone. UI labels should be concise; do not invent words or add narration."}};
  if(language=="fr")result.Add(new LocalGlossaryProfile{Id="celesphonia-fr",Name="Celesphonia · français",Language="fr",Context="Localisation française de Celesphonia, un RPG fantastique pour adultes. Employer un français naturel et les termes usuels du jeu. Les libellés de menu sont courts. Respecter le sens, les noms et le ton du texte de référence anglais. Ne pas inventer de mots. Conserver ATK, DEF, MAT, MDF, AGI, HP, MP et SP.",Terms=new List<LocalGlossaryTerm>{new LocalGlossaryTerm{Source="媚药",Target="aphrodisiaque"},new LocalGlossaryTerm{Source="媚薬",Target="aphrodisiaque"},new LocalGlossaryTerm{Source="aphrodisiac",Target="aphrodisiaque"},new LocalGlossaryTerm{Source="催眠",Target="hypnose"},new LocalGlossaryTerm{Source="hypnosis",Target="hypnose"},new LocalGlossaryTerm{Source="瘴气",Target="miasmes"}}});
  lock(profilesGate){string file=LocalTranslation.Child(Home,"profiles.json");string stamp=File.Exists(file)?File.GetLastWriteTimeUtc(file).Ticks+":"+new FileInfo(file).Length:"missing";if(stamp!=profilesStamp){cachedProfiles=LocalTranslation.Read<List<LocalGlossaryProfile>>(file);profilesStamp=stamp;}foreach(var value in cachedProfiles.Where(x=>x!=null&&(x.Language=="*"||x.Language==language))){result.RemoveAll(x=>x.Id==value.Id);result.Add(value);}}
  return result;
 }
 public static LocalGlossaryProfile Profile(LocalRun run,LocalRunOptions options){string id=string.IsNullOrEmpty(options.GlossaryProfileId)?(run.Language=="fr"?"celesphonia-fr":"rpg"):options.GlossaryProfileId;return Profiles(run.Language).FirstOrDefault(x=>x.Id==id)??Profiles(run.Language).First();}
 public static void SaveProfile(LocalGlossaryProfile profile){if(profile==null||string.IsNullOrWhiteSpace(profile.Name)||profile.Context==null||profile.Context.Length>5000||profile.Terms==null||profile.Terms.Count>500)throw new IOException("Give the profile a name; use at most 500 terms and 5,000 context characters.");profile.Terms=profile.Terms.Where(x=>x!=null&&!string.IsNullOrWhiteSpace(x.Source)&&!string.IsNullOrWhiteSpace(x.Target)).ToList();if(profile.Terms.Any(x=>x.Source.Length>200||x.Target.Length>200||x.Source.Contains("\\")||x.Target.Contains("\\")))throw new IOException("Glossary terms must be plain short terms, without game control codes.");if(string.IsNullOrEmpty(profile.Id))profile.Id=Guid.NewGuid().ToString("N");lock(profilesGate){var all=LocalTranslation.Read<List<LocalGlossaryProfile>>(LocalTranslation.Child(Home,"profiles.json"));all.RemoveAll(x=>x.Id==profile.Id);all.Add(profile);LocalTranslation.Write(LocalTranslation.Child(Home,"profiles.json"),all);profilesStamp=null;}}
 public static string Policy(LocalRun run,LocalRunOptions options,string source,string reference){var p=Profile(run,options);return LocalTranslation.TextHash(LocalTranslation.Json.Serialize(new{context=p.Context,english=options.ReferenceEnglish&&p.UseEnglishReference?reference:"",terms=options.UseGlossary?p.Terms.Where(x=>source.IndexOf(x.Source,StringComparison.OrdinalIgnoreCase)>=0).ToArray():new LocalGlossaryTerm[0]}));}
 static string PackFolder(string family,string language){return LocalTranslation.Child(Home,"Packs/"+Safe(family)+"/"+Safe(language));}
 static string Safe(string value){if(string.IsNullOrWhiteSpace(value)||!Regex.IsMatch(value,@"^[A-Za-z0-9_-]{1,100}$"))throw new IOException("Invalid dictionary identity.");return value;}
 public static List<LocalDictionaryPack> Packs(LocalRun run){string folder=PackFolder(Family(run),run.Language);if(!Directory.Exists(folder))return new List<LocalDictionaryPack>();return Directory.GetFiles(folder,"*.json").Select(x=>LocalTranslation.Read<LocalDictionaryPack>(x)).Where(x=>x.Kind=="Celesphonia.Dictionary"&&x.Family==Family(run)&&x.Language==run.Language).OrderBy(x=>x.Name).ToList();}
 public static IEnumerable<LocalRun> CompatibleRuns(LocalRun run){return LocalTranslation.Runs(null).Where(x=>x.Language==run.Language&&Family(x)==Family(run));}
 public static Dictionary<string,LocalResult> ModelRows(LocalRun run,bool includePrevious){
  var covered=EnglishSupport.CoveredLocalSources(run.Root);var output=new Dictionary<string,LocalResult>();var ambiguous=new HashSet<string>();var candidates=includePrevious?CompatibleRuns(run).OrderBy(x=>x.Id==run.Id?1:0).ThenBy(x=>x.Updated):new[]{run}.AsEnumerable();
  foreach(var other in candidates.Where(x=>x.Id==run.Id||x.ModelHash==run.ModelHash))foreach(var row in LocalTranslation.Results(other.Id).Values){string role;if(covered.TryGetValue(row.Source,out role)&&(row.Category!=role||!Valid(row.Source,row.Target)))continue;if(other.Id!=run.Id&&!covered.ContainsKey(row.Source))continue;LocalResult prior;if(output.TryGetValue(row.Source,out prior)&&prior.Target!=row.Target&&other.Id!=run.Id){ambiguous.Add(row.Source);continue;}if(other.Id==run.Id)ambiguous.Remove(row.Source);output[row.Source]=row;}
  foreach(string source in ambiguous)output.Remove(source);return output;
 }
 public static LocalComparison Compare(LocalRun run){Bind(run);var value=new LocalComparison{English=EnglishSupport.LocalReference(run.Root),Edits=LocalTranslation.Edits(run.Id)};var options=LocalTranslation.Options(run);value.ModelRows=ModelRows(run,true);foreach(var pair in value.ModelRows)value.Model[pair.Key]=pair.Value.Target;
  var covered=EnglishSupport.CoveredLocalSources(run.Root);foreach(var pack in Packs(run))value.Packs[pack.Id]=pack;foreach(string id in options.PackIds??new string[0]){LocalDictionaryPack pack;if(!value.Packs.TryGetValue(id,out pack))continue;foreach(var row in pack.Entries){string role;if(covered.TryGetValue(row.Source,out role)&&(string.IsNullOrEmpty(row.Role)||row.Role==role)&&Valid(row.Source,row.Target)){value.Imported[row.Source]=row.Target;value.Origins[row.Source]="Imported · "+pack.Name;}}}
  foreach(var edit in value.Edits.Values)if(edit.Target!=null&&!edit.Deferred&&!edit.LeaveOriginal&&covered.ContainsKey(edit.Source)&&covered[edit.Source]==edit.Category&&Valid(edit.Source,edit.Target))value.User[edit.Source]=edit.Target;
  foreach(var pair in value.Model){value.Effective[pair.Key]=pair.Value;if(!value.Origins.ContainsKey(pair.Key))value.Origins[pair.Key]="Model";}foreach(var pair in value.Imported)value.Effective[pair.Key]=pair.Value;foreach(var pair in value.User){value.Effective[pair.Key]=pair.Value;value.Origins[pair.Key]="User override";}return value;
 }
 public static Dictionary<string,string> Layer(LocalComparison value,string layer){if(layer=="model")return value.Model;if(layer=="user")return value.User;if(layer=="imported")return value.Imported;if(layer!=null&&layer.StartsWith("pack:")){LocalDictionaryPack pack;if(value.Packs.TryGetValue(layer.Substring(5),out pack)){lock(value.PackLayers){Dictionary<string,string> cached;if(!value.PackLayers.TryGetValue(pack.Id,out cached)){cached=pack.Entries.GroupBy(x=>x.Source).ToDictionary(x=>x.Key,x=>x.Last().Target);value.PackLayers[pack.Id]=cached;}return cached;}}return new Dictionary<string,string>();}return value.Effective;}
 public static void Carryover(LocalRun run){Bind(run);var covered=EnglishSupport.CoveredLocalSources(run.Root);var edits=LocalTranslation.Edits(run.Id);var previous=CompatibleRuns(run).Where(x=>x.Id!=run.Id).ToList();foreach(var item in previous.SelectMany(x=>LocalTranslation.Edits(x.Id).Values).OrderByDescending(x=>x.Updated)){string role;if(!covered.TryGetValue(item.Source,out role)||role!=item.Category||item.Target!=null&&!Valid(item.Source,item.Target))continue;string key=Key(role,item.Source);if(edits.ContainsKey(key))continue;edits[key]=new LocalEdit{Key=key,Source=item.Source,Category=role,Context="EnglishCoverage",Target=item.Target,LeaveOriginal=item.LeaveOriginal,Deferred=item.Deferred,Updated=item.Updated,Fields=item.Target==null?null:EnglishSupport.PrepareLocalField(run.Root,item.Source,item.Target)};}if(edits.Count>0)LocalTranslation.Write(LocalTranslation.RunFile(run.Id,"overrides.json"),edits);var latest=previous.FirstOrDefault();if(latest!=null){var options=LocalTranslation.Options(run);var prior=LocalTranslation.Options(latest);options.PackIds=prior.PackIds;options.GlossaryProfileId=prior.GlossaryProfileId;options.UseGlossary=prior.UseGlossary;options.ReferenceEnglish=prior.ReferenceEnglish;options.Backend=prior.Backend;options.Device=prior.Device;options.Threads=prior.Threads;options.GpuLayers=prior.GpuLayers;options.IncludeSources=(prior.IncludeSources??new string[0]).Where(x=>covered.ContainsKey(x)).ToArray();LocalTranslation.SetOptions(run.Id,options);}}
 public static void Publish(LocalRun run){
  Bind(run);var options=LocalTranslation.Options(run);var covered=EnglishSupport.CoveredLocalSources(run.Root);var comparison=Compare(run);var selected=Layer(comparison,options.RenderLayer);if(options.RenderLayer!=null&&options.RenderLayer.StartsWith("pack:")){LocalDictionaryPack chosen;if(comparison.Packs.TryGetValue(options.RenderLayer.Substring(5),out chosen)){var compatible=new HashSet<string>(chosen.Entries.Where(x=>covered.ContainsKey(x.Source)&&(string.IsNullOrEmpty(x.Role)||x.Role==covered[x.Source])).Select(x=>x.Source));selected=selected.Where(x=>compatible.Contains(x.Key)).ToDictionary(x=>x.Key,x=>x.Value);}}var data=new Dictionary<string,string>();foreach(var pair in selected){string role;if(!covered.TryGetValue(pair.Key,out role)||!Selected(options,role,pair.Key)||!Valid(pair.Key,pair.Value))continue;LocalEdit edit;if(comparison.Edits.TryGetValue(Key(role,pair.Key),out edit)&&(edit.Deferred||edit.LeaveOriginal))continue;data[pair.Key]=pair.Value;}
  var baseData=new Dictionary<string,string>();if(options.RenderLayer=="effective"||options.RenderLayer=="model")foreach(var pair in comparison.Model){string role;if(covered.TryGetValue(pair.Key,out role)&&Selected(options,role,pair.Key)&&Valid(pair.Key,pair.Value)){LocalEdit edit;if(comparison.Edits.TryGetValue(Key(role,pair.Key),out edit)&&(edit.LeaveOriginal||edit.Deferred))continue;baseData[pair.Key]=pair.Value;}}
  if(options.RenderLayer=="effective")data=data.Where(x=>comparison.Imported.ContainsKey(x.Key)||comparison.User.ContainsKey(x.Key)).ToDictionary(x=>x.Key,x=>x.Value);else if(options.RenderLayer=="model")data.Clear();
  var fields=EnglishSupport.PrepareLocalData(run.Root,data);var baseFields=EnglishSupport.PrepareLocalData(run.Root,baseData);LocalTranslation.Write(LocalTranslation.RunFile(run.Id,"layers.json"),new{format=2,revision=Revision(run),layer=options.RenderLayer,baseFields=baseFields,fields=fields,covered=covered});LocalTranslation.Write(LocalTranslation.RunFile(run.Id,"layers-meta.json"),new{generation=Guid.NewGuid().ToString("N"),coverage=Revision(run),layer=options.RenderLayer});

 }
 public static bool Selected(LocalRunOptions options,string role,string source){return options.Scope.Contains(role)||(options.IncludeSources??new string[0]).Contains(source)||(options.IncludeKeys??new string[0]).Contains(Key(role,source));}
 public static LocalImportPreview Parse(string file,LocalRun run){
  string text=ReadImportText(file);var pack=new LocalDictionaryPack{Name=Path.GetFileNameWithoutExtension(file),Family=Family(run),OriginVersion=run.OriginVersion??Version(run.Root),Language=run.Language};object native=null;
  try{native=LocalTranslation.Json.DeserializeObject(text);}catch(ArgumentException){var rows=new List<object>();foreach(string line in text.Split('\n').Where(x=>!string.IsNullOrWhiteSpace(x)))rows.Add(LocalTranslation.Json.DeserializeObject(line));native=rows.ToArray();}
  var obj=native as Dictionary<string,object>;if(obj!=null&&obj.ContainsKey("Kind")){pack=LocalTranslation.Json.Deserialize<LocalDictionaryPack>(text);if(pack.Kind!="Celesphonia.Dictionary"||pack.Format!=1)throw new IOException("Unsupported dictionary pack schema.");if(pack.Family!=Family(run)||pack.Language!=run.Language)throw new IOException("This pack is for "+pack.Family+" / "+pack.Language+". Select a matching game/language run.");}
  else if(obj!=null&&!obj.ContainsKey("Source")){foreach(var item in obj){if(!(item.Value is string))throw new IOException("Expected a source-to-translation JSON dictionary.");pack.Entries.Add(new LocalContentEntry{Source=item.Key,Target=(string)item.Value});}}
  else {var array=native as IEnumerable;if(obj!=null)array=new[]{obj};if(array==null)throw new IOException("Expected a dictionary or translation-row list.");foreach(object item in array){var row=item as Dictionary<string,object>;if(row==null||!row.ContainsKey("Source")||!row.ContainsKey("Target"))throw new IOException("Translation rows require Source and Target strings.");pack.Entries.Add(new LocalContentEntry{Source=Convert.ToString(row["Source"]),Target=Convert.ToString(row["Target"]),Role=row.ContainsKey("Category")?Convert.ToString(row["Category"]):null});}}
  if(pack.Entries==null||pack.Entries.Count>100000)throw new IOException("Dictionary entry limit exceeded.");var covered=EnglishSupport.CoveredLocalSources(run.Root);var current=Compare(run);var result=new LocalImportPreview{Pack=pack};var unique=new Dictionary<string,LocalContentEntry>();
  foreach(var entry in pack.Entries){if(entry==null){result.Invalid++;continue;}if(entry.Source==entry.Target){result.Unchanged++;continue;}if(!Valid(entry.Source,entry.Target)){result.Invalid++;continue;}LocalContentEntry duplicate;if(unique.TryGetValue(entry.Source,out duplicate)&&duplicate.Target!=entry.Target)throw new IOException("Conflicting duplicate source in the imported file: "+entry.Source.Substring(0,Math.Min(60,entry.Source.Length)));entry.SourceHash=LocalTranslation.TextHash(entry.Source);if(string.IsNullOrEmpty(entry.Origin))entry.Origin="imported";unique[entry.Source]=entry;string role;if(covered.TryGetValue(entry.Source,out role)&&(string.IsNullOrEmpty(entry.Role)||entry.Role==role)){entry.Role=role;result.Applicable++;string target;if(current.Effective.TryGetValue(entry.Source,out target)&&target!=entry.Target)result.Conflicts++;}else result.Inactive++;}
  pack.Entries=unique.Values.ToList();if(string.IsNullOrEmpty(pack.Id))pack.Id=LocalTranslation.TextHash(text).Substring(0,32);Safe(pack.Id);result.Summary=result.Applicable.ToString("N0")+" currently applicable · "+result.Inactive.ToString("N0")+" retained inactive until compatible coverage\r\n"+result.Conflicts.ToString("N0")+" differing current targets · "+result.Invalid.ToString("N0")+" invalid · "+result.Unchanged.ToString("N0")+" unchanged templates\r\n\r\n"+pack.Family+" · "+pack.OriginVersion+" · "+pack.Language+"\r\nUser overrides keep precedence. Curated English stays unchanged.";return result;
 }
 static string ReadBounded(Stream stream){using(var memory=new MemoryStream()){byte[] buffer=new byte[65536];int count;while((count=stream.Read(buffer,0,buffer.Length))>0){if(memory.Length+count>48*1024*1024)throw new IOException("Expanded dictionary exceeds 48 MiB.");memory.Write(buffer,0,count);}return Encoding.UTF8.GetString(memory.ToArray()).TrimStart('\ufeff');}}
 static string ReadImportText(string file){if(new FileInfo(file).Length>48*1024*1024)throw new IOException("Dictionary file exceeds 48 MiB.");using(var stream=File.OpenRead(file)){if(stream.ReadByte()==0x50&&stream.ReadByte()==0x4b){stream.Position=0;using(var zip=new ZipArchive(stream,ZipArchiveMode.Read)){if(zip.Entries.Count>1024)throw new IOException("Too many dictionary archive entries.");var entries=zip.Entries.Where(x=>!x.FullName.EndsWith("/")).ToArray();if(entries.Any(x=>x.FullName.Contains("..")||x.FullName.Contains(":")||x.FullName.StartsWith("/")||x.FullName.StartsWith("\\")))throw new IOException("Unsafe dictionary archive path.");var matches=entries.Where(x=>Path.GetFileName(x.FullName).Equals("dictionary-pack.json",StringComparison.OrdinalIgnoreCase)).ToArray();if(matches.Length==0)matches=entries.Where(x=>Path.GetFileName(x.FullName).Equals("dictionary.json",StringComparison.OrdinalIgnoreCase)).ToArray();if(matches.Length!=1||matches[0].Length>48*1024*1024)throw new IOException("Archive must contain one dictionary-pack.json or dictionary.json within 48 MiB.");using(var entry=matches[0].Open())return ReadBounded(entry);}}stream.Position=0;return ReadBounded(stream);}}
 public static void Import(LocalRun run,LocalImportPreview preview,bool enable){var pack=preview.Pack;string folder=PackFolder(pack.Family,pack.Language);Directory.CreateDirectory(folder);string file=LocalTranslation.Child(folder,Safe(pack.Id)+".json");if(File.Exists(file)){string backup=LocalTranslation.Child(Home,"Backups/"+pack.Id+"-"+DateTime.UtcNow.Ticks+".json");Directory.CreateDirectory(Path.GetDirectoryName(backup));File.Copy(file,backup);}LocalTranslation.Write(file,pack);if(enable){var options=LocalTranslation.Options(run);options.PackIds=(options.PackIds??new string[0]).Where(x=>x!=pack.Id).Concat(new[]{pack.Id}).ToArray();LocalTranslation.SetOptions(run.Id,options);}Publish(run);}
 public static void Export(string file,LocalRun run,IEnumerable<string> sources,string layer,bool includeProfile){var comparison=Compare(run);var values=Layer(comparison,layer);var covered=EnglishSupport.CoveredLocalSources(run.Root);var pack=new LocalDictionaryPack{Id=Guid.NewGuid().ToString("N"),Name=Path.GetFileNameWithoutExtension(file),Family=Family(run),OriginVersion=run.OriginVersion,Language=run.Language,Glossary=includeProfile?Profile(run,LocalTranslation.Options(run)):null};foreach(string source in sources.Distinct()){string target;if(!values.TryGetValue(source,out target)||!Valid(source,target))continue;string english;comparison.English.TryGetValue(source,out english);pack.Entries.Add(new LocalContentEntry{Source=source,Target=target,Role=covered.ContainsKey(source)?covered[source]:null,SourceHash=LocalTranslation.TextHash(source),ReferenceHash=LocalTranslation.TextHash(english??""),Origin=layer,OriginVersion=run.OriginVersion});}if(pack.Entries.Count==0)throw new IOException("The selected layer has no valid translations to export.");LocalTranslation.Atomic(file,Encoding.UTF8.GetBytes(LocalTranslation.Json.Serialize(pack)));}
 public static int Batch(LocalRun run,IEnumerable<LocalUnit> selected,string action){var rows=selected.GroupBy(x=>x.Key).Select(x=>x.First()).ToList();var covered=EnglishSupport.CoveredLocalSources(run.Root);if(rows.Any(x=>!covered.ContainsKey(x.Source)))throw new IOException("Inactive/uncovered rows cannot be queued or changed. Filter to covered rows first.");
  var options=LocalTranslation.Options(run);using(var lease=new FileStream(LocalTranslation.RunFile(run.Id,"edit.lock"),FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None)){var edits=LocalTranslation.Edits(run.Id);foreach(var row in rows){if(action=="clear"){edits.Remove(row.Key);continue;}LocalEdit edit;if(!edits.TryGetValue(row.Key,out edit))edit=new LocalEdit{Key=row.Key,Source=row.Source,Category=covered[row.Source],Context="EnglishCoverage"};if(action=="defer")edit.Deferred=true;else if(action=="original"){edit.LeaveOriginal=true;edit.Deferred=false;}else if(action=="queue"||action=="regenerate"){edit.LeaveOriginal=edit.Deferred=false;}edit.Updated=DateTimeOffset.Now.ToString("o");edits[row.Key]=edit;}LocalTranslation.Write(LocalTranslation.RunFile(run.Id,"overrides.json"),edits);}
  if(action=="queue"||action=="regenerate"){options.IncludeKeys=(options.IncludeKeys??new string[0]).Concat(rows.Select(x=>x.Key)).Distinct().ToArray();options.IncludeSources=(options.IncludeSources??new string[0]).Concat(rows.Select(x=>x.Source)).Distinct().ToArray();if(action=="regenerate"){options.RegenerateGeneration++;options.RegenerateKeys=rows.Select(x=>x.Key).ToArray();options.RetryGeneration++;options.RetryKeys=options.RegenerateKeys;}}
  LocalTranslation.SetOptions(run.Id,options);Publish(run);if(action=="queue"||action=="regenerate")LocalTranslation.Control(run.Id,"run");return rows.Count;
 }
}
